{
  "items": [
    {
      "name": "IsAlgebraic.exists_integral_multiple",
      "module_name": "Mathlib.RingTheory.Algebraic.Integral",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} [inst : CommRing R] [inst_1 : Ring A] [inst_2 : Algebra R A] {z : A},\n  IsAlgebraic R z → ∃ y, y ≠ 0 ∧ IsIntegral R (y • z)"
    },
    {
      "name": "IsAlgebraic.isIntegral",
      "module_name": "Mathlib.RingTheory.Algebraic.Integral",
      "kind": "theorem",
      "type": "∀ {K : Type u} {A : Type v} [inst : Field K] [inst_1 : Ring A] [inst_2 : Algebra K A] {x : A},\n  IsAlgebraic K x → IsIntegral K x"
    },
    {
      "name": "mem_integralClosure_iff",
      "module_name": "Mathlib.RingTheory.IntegralClosure.Algebra.Basic",
      "kind": "theorem",
      "type": "∀ (R : Type u_1) (A : Type u_2) [inst : CommRing R] [inst_1 : CommRing A] [inst_2 : Algebra R A] {a : A},\n  a ∈ integralClosure R A ↔ IsIntegral R a"
    },
    {
      "name": "integralClosure.isIntegral",
      "module_name": "Mathlib.RingTheory.IntegralClosure.IsIntegralClosure.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_2} [inst : CommRing R] [inst_1 : CommRing A] [inst_2 : Algebra R A]\n  (x : ↥(integralClosure R A)), IsIntegral R x"
    },
    {
      "name": "integralClosure",
      "module_name": "Mathlib.RingTheory.IntegralClosure.Algebra.Basic",
      "kind": "definition",
      "type": "(R : Type u_1) → (A : Type u_2) → [inst : CommRing R] → [inst_1 : CommRing A] → [inst_2 : Algebra R A] → Subalgebra R A"
    },
    {
      "name": "IsIntegralClosure.isIntegral_algebra",
      "module_name": "Mathlib.RingTheory.IntegralClosure.IsIntegralClosure.Basic",
      "kind": "theorem",
      "type": "∀ (R : Type u_1) {A : Type u_2} (B : Type u_3) [inst : CommRing R] [inst_1 : CommRing A] [inst_2 : CommRing B]\n  [inst_3 : Algebra R B] [inst_4 : Algebra A B] [IsIntegralClosure A R B] [inst_6 : Algebra R A] [IsScalarTower R A B],\n  Algebra.IsIntegral R A"
    },
    {
      "name": "algebraicClosure.isIntegralClosure",
      "module_name": "Mathlib.FieldTheory.AlgebraicClosure",
      "kind": "instance",
      "type": "∀ (F : Type u_1) (E : Type u_2) [inst : Field F] [inst_1 : Field E] [inst_2 : Algebra F E],\n  IsIntegralClosure (↥(algebraicClosure F E)) F E"
    },
    {
      "name": "IsIntegralClosure.isIntegral",
      "module_name": "Mathlib.RingTheory.IntegralClosure.IsIntegralClosure.Basic",
      "kind": "theorem",
      "type": "∀ (R : Type u_1) {A : Type u_2} (B : Type u_3) [inst : CommRing R] [inst_1 : CommRing A] [inst_2 : CommRing B]\n  [inst_3 : Algebra R B] [inst_4 : Algebra A B] [IsIntegralClosure A R B] [inst_6 : Algebra R A] [IsScalarTower R A B]\n  (x : A), IsIntegral R x"
    }
  ]
}
